-- Verificar KEURE QUIMICA na planilha
SELECT empresa, vencimento, valor, status FROM cobranca_planilha 
WHERE UPPER(empresa) LIKE '%KEURE%' ORDER BY vencimento;

-- Verificar RONALDO na planilha
SELECT empresa, vencimento, valor, status FROM cobranca_planilha 
WHERE UPPER(empresa) LIKE '%RONALDO%' ORDER BY vencimento;

-- Verificar M D DA SILVA na planilha
SELECT empresa, vencimento, valor, status FROM cobranca_planilha 
WHERE UPPER(empresa) LIKE '%M D DA SILVA%' ORDER BY vencimento;

